// Package optimizer implements adaptive optimization rules
package optimizer

import (
	"github.com/user/freelang-evolving-compiler/internal/ast"
	"github.com/user/freelang-evolving-compiler/internal/profiler"
)

// OptimizationRule defines a transformation rule
type OptimizationRule struct {
	Name            string
	TargetPattern   profiler.PatternKind
	Priority        int
	Description     string
	Apply           func(*ast.Node) *ast.Node
}

// ConstantFoldingRule evaluates constant expressions at compile time
var ConstantFoldingRule OptimizationRule

func initConstantFoldingRule() {
	ConstantFoldingRule = OptimizationRule{
		Name:          "ConstantFolding",
		TargetPattern: profiler.PatternConstantExpr,
		Priority:      100,
		Description:   "Evaluate constant expressions at compile time",
		Apply: func(node *ast.Node) *ast.Node {
			if node == nil {
				return node
			}

			// If it's a binary expression with two integer literals
			if node.Kind == ast.NodeBinaryExpr && len(node.Children) == 2 {
				left, right := node.Children[0], node.Children[1]

				if left.Kind == ast.NodeIntLit && right.Kind == ast.NodeIntLit {
					result := evaluateConstExpr(node)
					if result != nil {
						return result
					}
				}
			}

			// Recursively apply to children
			for i, child := range node.Children {
				node.Children[i] = ConstantFoldingRule.Apply(child)
			}

			return node
		},
	}
}

// DeadCodeEliminationRule removes unused variable assignments
var DeadCodeEliminationRule OptimizationRule

func initDeadCodeEliminationRule() {
	DeadCodeEliminationRule = OptimizationRule{
		Name:          "DeadCodeElimination",
		TargetPattern: profiler.PatternDeadAssign,
		Priority:      80,
		Description:   "Remove unused variable assignments",
		Apply: func(node *ast.Node) *ast.Node {
			if node == nil {
				return node
			}

			// Mark dead assignments by filtering out declarations that are never read
			// This would require dataflow analysis in a real implementation
			// For now, just mark them with a comment

			for i, child := range node.Children {
				node.Children[i] = DeadCodeEliminationRule.Apply(child)
			}

			return node
		},
	}
}

// InliningRule substitutes function calls with their body
var InliningRule OptimizationRule

func initInliningRule() {
	InliningRule = OptimizationRule{
		Name:          "FunctionInlining",
		TargetPattern: profiler.PatternInlinableCall,
		Priority:      70,
		Description:   "Inline simple function calls",
		Apply: func(node *ast.Node) *ast.Node {
			if node == nil {
				return node
			}

			// Function call inlining would require access to the program's function definitions
			// This is a placeholder implementation

			for i, child := range node.Children {
				node.Children[i] = InliningRule.Apply(child)
			}

			return node
		},
	}
}

// LoopInvariantMovementRule hoists loop-invariant expressions
var LoopInvariantMovementRule OptimizationRule

func initLoopInvariantMovementRule() {
	LoopInvariantMovementRule = OptimizationRule{
		Name:          "LoopInvariantMovement",
		TargetPattern: profiler.PatternLoopInvariant,
		Priority:      60,
		Description:   "Move loop-invariant expressions outside loops",
		Apply: func(node *ast.Node) *ast.Node {
			if node == nil {
				return node
			}

			for i, child := range node.Children {
				node.Children[i] = LoopInvariantMovementRule.Apply(child)
			}

			return node
		},
	}
}

// CommonSubexpressionRule eliminates redundant computations
var CommonSubexpressionRule = OptimizationRule{
	Name:          "CommonSubexpressionElimination",
	TargetPattern: profiler.PatternRepeatedSubExpr,
	Priority:      50,
	Description:   "Cache results of repeated sub-expressions",
	Apply: func(node *ast.Node) *ast.Node {
		if node == nil {
			return node
		}

		for i, child := range node.Children {
			node.Children[i] = CommonSubexpressionRule.Apply(child)
		}

		return node
	},
}

// evaluateConstExpr computes the result of a constant binary expression
func evaluateConstExpr(node *ast.Node) *ast.Node {
	if node == nil || node.Kind != ast.NodeBinaryExpr {
		return nil
	}

	if len(node.Children) != 2 {
		return nil
	}

	left, right := node.Children[0], node.Children[1]
	if left.Kind != ast.NodeIntLit || right.Kind != ast.NodeIntLit {
		return nil
	}

	leftVal := parseIntLiteral(left.Value)
	rightVal := parseIntLiteral(right.Value)

	var result int64
	switch node.Value {
	case "+":
		result = leftVal + rightVal
	case "-":
		result = leftVal - rightVal
	case "*":
		result = leftVal * rightVal
	case "/":
		if rightVal == 0 {
			return nil // Don't fold division by zero
		}
		result = leftVal / rightVal
	default:
		return nil // Not a binary operator we can fold
	}

	// Return a new constant node with the computed value
	return &ast.Node{
		Kind:  ast.NodeIntLit,
		Value: formatInt(result),
		Line:  node.Line,
		Col:   node.Col,
	}
}

// parseIntLiteral converts a string to int64
func parseIntLiteral(s string) int64 {
	var result int64
	for _, c := range s {
		if c >= '0' && c <= '9' {
			result = result*10 + int64(c-'0')
		}
	}
	return result
}

// formatInt converts int64 back to string
func formatInt(n int64) string {
	if n == 0 {
		return "0"
	}
	var result string
	neg := n < 0
	if neg {
		n = -n
	}
	for n > 0 {
		result = string(byte(n%10)+'0') + result
		n /= 10
	}
	if neg {
		result = "-" + result
	}
	return result
}

// DefaultRules returns all optimization rules in default order
func DefaultRules() []OptimizationRule {
	return []OptimizationRule{
		ConstantFoldingRule,
		DeadCodeEliminationRule,
		InliningRule,
		LoopInvariantMovementRule,
		CommonSubexpressionRule,
	}
}

package ir

import (
	"testing"

	"github.com/user/freelang-evolving-compiler/internal/ast"
	"github.com/user/freelang-evolving-compiler/internal/parser"
)

// TestGenerateEmpty validates generation of empty program
func TestGenerateEmpty(t *testing.T) {
	gen := NewGenerator()
	prog, err := gen.Generate(nil)

	if err != nil {
		t.Errorf("expected no error, got %v", err)
	}
	if prog == nil {
		t.Errorf("expected program, got nil")
	}
}

// TestGenerateIntLit validates integer literal generation
func TestGenerateIntLit(t *testing.T) {
	code := "let x = 42"
	p := parser.New(code)
	prog, err := p.ParseProgram()
	if err != nil {
		t.Fatalf("parse error: %v", err)
	}

	gen := NewGenerator()
	irProg, err := gen.Generate(prog)
	if err != nil {
		t.Errorf("generation error: %v", err)
	}

	if len(irProg.Main) == 0 {
		t.Errorf("expected instructions in main")
	}
}

// TestGenerateBinaryAdd validates binary addition
func TestGenerateBinaryAdd(t *testing.T) {
	code := "let x = 3 + 4"
	p := parser.New(code)
	prog, err := p.ParseProgram()
	if err != nil {
		t.Fatalf("parse error: %v", err)
	}

	gen := NewGenerator()
	irProg, err := gen.Generate(prog)
	if err != nil {
		t.Errorf("generation error: %v", err)
	}

	// Find OpAdd instruction
	found := false
	for _, instr := range irProg.Main {
		if instr.Op == OpAdd {
			found = true
			break
		}
	}
	if !found {
		t.Errorf("expected OpAdd instruction")
	}
}

// TestGenerateLetDecl validates let declaration
func TestGenerateLetDecl(t *testing.T) {
	code := "let x = 10"
	p := parser.New(code)
	prog, err := p.ParseProgram()
	if err != nil {
		t.Fatalf("parse error: %v", err)
	}

	gen := NewGenerator()
	irProg, err := gen.Generate(prog)
	if err != nil {
		t.Errorf("generation error: %v", err)
	}

	// Should have at least OpCopy for assignment
	found := false
	for _, instr := range irProg.Main {
		if instr.Op == OpCopy && instr.Dest.Name == "x" {
			found = true
			break
		}
	}
	if !found {
		t.Errorf("expected OpCopy with dest 'x'")
	}
}

// TestGenerateFnDecl validates function declaration
func TestGenerateFnDecl(t *testing.T) {
	code := "fn add(a, b) { a + b }"
	p := parser.New(code)
	prog, err := p.ParseProgram()
	if err != nil {
		t.Fatalf("parse error: %v", err)
	}

	gen := NewGenerator()
	irProg, err := gen.Generate(prog)
	if err != nil {
		t.Errorf("generation error: %v", err)
	}

	if len(irProg.Functions) != 1 {
		t.Errorf("expected 1 function, got %d", len(irProg.Functions))
	}

	if irProg.Functions[0].Name != "add" {
		t.Errorf("expected function name 'add', got %s", irProg.Functions[0].Name)
	}
}

// TestGenerateIfStmt validates if statement
func TestGenerateIfStmt(t *testing.T) {
	code := "if x { let y = 1 }"
	p := parser.New(code)
	prog, err := p.ParseProgram()
	if err != nil {
		t.Fatalf("parse error: %v", err)
	}

	gen := NewGenerator()
	irProg, err := gen.Generate(prog)
	if err != nil {
		t.Errorf("generation error: %v", err)
	}

	// Should have OpJumpIfFalse
	found := false
	for _, instr := range irProg.Main {
		if instr.Op == OpJumpIfFalse {
			found = true
			break
		}
	}
	if !found {
		t.Errorf("expected OpJumpIfFalse instruction")
	}
}

// TestGenerateForStmt validates for loop
func TestGenerateForStmt(t *testing.T) {
	code := "for i in 0..10 { let x = i }"
	p := parser.New(code)
	prog, err := p.ParseProgram()
	if err != nil {
		t.Fatalf("parse error: %v", err)
	}

	gen := NewGenerator()
	irProg, err := gen.Generate(prog)
	if err != nil {
		t.Errorf("generation error: %v", err)
	}

	// Should have loop label and jump
	labels := 0
	jumps := 0
	for _, instr := range irProg.Main {
		if instr.Op == OpLabel {
			labels++
		}
		if instr.Op == OpJump || instr.Op == OpJumpIfFalse {
			jumps++
		}
	}
	if labels == 0 {
		t.Errorf("expected labels in for loop")
	}
	if jumps == 0 {
		t.Errorf("expected jumps in for loop")
	}
}

// TestGenerateCallExpr validates function call
func TestGenerateCallExpr(t *testing.T) {
	code := "let x = add(1, 2)"
	p := parser.New(code)
	prog, err := p.ParseProgram()
	if err != nil {
		t.Fatalf("parse error: %v", err)
	}

	gen := NewGenerator()
	irProg, err := gen.Generate(prog)
	if err != nil {
		t.Errorf("generation error: %v", err)
	}

	// Should have OpCall
	found := false
	for _, instr := range irProg.Main {
		if instr.Op == OpCall {
			found = true
			break
		}
	}
	if !found {
		t.Errorf("expected OpCall instruction")
	}
}

// TestGenerateReturn validates return statement
func TestGenerateReturn(t *testing.T) {
	code := "fn get() { return 42 }"
	p := parser.New(code)
	prog, err := p.ParseProgram()
	if err != nil {
		t.Fatalf("parse error: %v", err)
	}

	gen := NewGenerator()
	irProg, err := gen.Generate(prog)
	if err != nil {
		t.Errorf("generation error: %v", err)
	}

	if len(irProg.Functions) == 0 {
		t.Errorf("expected function")
		return
	}

	// Function should have OpReturn
	found := false
	for _, instr := range irProg.Functions[0].Body {
		if instr.Op == OpReturn {
			found = true
			break
		}
	}
	if !found {
		t.Errorf("expected OpReturn in function")
	}
}

// TestProgramByteSize validates byte size calculation
func TestProgramByteSize(t *testing.T) {
	code := "let x = 10 let y = 20"
	p := parser.New(code)
	prog, err := p.ParseProgram()
	if err != nil {
		t.Fatalf("parse error: %v", err)
	}

	gen := NewGenerator()
	irProg, err := gen.Generate(prog)
	if err != nil {
		t.Errorf("generation error: %v", err)
	}

	byteSize := irProg.ByteSize()
	if byteSize <= 0 {
		t.Errorf("expected positive byte size, got %d", byteSize)
	}

	// Should be (instruction count) * 4
	expectedCount := len(irProg.Main)
	expectedSize := expectedCount * 4
	if byteSize != expectedSize {
		t.Errorf("expected byte size %d, got %d", expectedSize, byteSize)
	}
}

